import { existsSync } from "@std/fs";
import { commands } from "@bsv/cli/commands.ts";
import { config } from "@bsv/cli/config.ts";
import { BSV_NIX_PREFIX, BSV_ROOT, BSV_TMP_DIR } from "@bsv/cli/constants.ts";
import { printHelp } from "@bsv/cli/print_help.ts";
import { DiagnosticConsole, LogLevel } from "@bsv/utils/console.ts";
import { parseArgs } from "@bsv/utils/parse_args.ts";
import { samefileSync } from "@bsv/utils/samefile.ts";

async function main() {
  const logLevel = (() => {
    switch (config.loglevel ?? "info") {
      case "debug":
        return LogLevel.DEBUG;
      case "info":
        return LogLevel.INFO;
      case "warn":
        return LogLevel.WARN;
      case "error":
        return LogLevel.ERROR;
      default:
        console.warn("warning: unknown `loglevel` setting, defaulting to info");
    }
  })();

  globalThis.console = new DiagnosticConsole(logLevel);

  // Set up common environment variables shared with other programs.
  Deno.env.set("http_proxy", "http://10.0.1.18:3128");
  Deno.env.set("https_proxy", "http://10.0.1.18:3128");
  Deno.env.set("ftp_proxy", "http://10.0.1.18:3128");
  Deno.env.set("no_proxy", "127.0.0.1,localhost,andestech.com");

  Deno.env.set(
    "MANPATH",
    `${BSV_NIX_PREFIX}/share/man:${Deno.env.get("MANPATH") ?? ""}`,
  );
  Deno.env.set("PATH", `/bsv/bin:${Deno.env.get("PATH") ?? ""}`);
  Deno.env.set("TMPDIR", BSV_TMP_DIR);

  // Set up environment variables used by Nix.
  Deno.env.delete("NIX_PATH");
  Deno.env.delete("NIX_PROFILES");
  Deno.env.delete("NIX_REMOTE");
  Deno.env.set("NIX_CONF_DIR", `${BSV_NIX_PREFIX}/etc`);
  Deno.env.set("NIX_DATA_DIR", `${BSV_NIX_PREFIX}/share`);
  Deno.env.set("NIX_STORE_DIR", `/nix/store`);
  Deno.env.set("NIX_LOG_DIR", `/nix/var/log/nix`);
  Deno.env.set("NIX_STATE_DIR", `/nix/var/nix`);
  Deno.env.set("NIX_CONFIG_HOME", `${BSV_TMP_DIR}/nix-config`);
  Deno.env.set("NIX_STATE_HOME", `${BSV_TMP_DIR}/nix-state`);
  Deno.env.set("NIX_CACHE_HOME", `${BSV_TMP_DIR}/nix-cache`);
  Deno.env.set("NIX_USER_CONF_FILES", `${BSV_ROOT}/nix.conf`);

  for (
    const path of [
      "/etc/ssl/certs/ca-certificates.crt",
      "/etc/pki/tls/certs/ca-bundle.crt",
      "/etc/ssl/certs/ca-bundle.crt",
      "/etc/ssl/cert.pem",
    ]
  ) {
    if (existsSync(path, { isFile: true, isReadable: true })) {
      Deno.env.set("NIX_SSL_CERT_FILE", path);
      break;
    }
  }

  const isKvmAvailable = (() => {
    try {
      const file = Deno.openSync("/dev/kvm", { read: true, write: true });
      file.close();
      return true;
    } catch {
      return false;
    }
  })();

  const nixConfig: Record<string, string> = {};

  if (isKvmAvailable) {
    nixConfig["extra-system-features"] = "kvm";
    nixConfig["extra-platforms"] = "bsv-builtin x86_64-windows";
  }

  Deno.env.set(
    "NIX_CONFIG",
    Object.entries(nixConfig).map(([key, value]) => `${key} = ${value}`).join(
      "\n",
    ),
  );

  const args = parseArgs(Deno.args, {
    boolean: ["help"],
    positional: true,
    stopEarly: true,
  });

  if (args.help) {
    await printHelp();
    Deno.exit(0);
  }

  const cmdName = args._[0];
  if (!cmdName) {
    await printHelp();
    Deno.exit(1);
  }

  const cmd = commands[cmdName];
  if (!cmd) {
    await printHelp();
    Deno.exit(1);
  }

  if (cmd.requiresBsvEnv) {
    if (!existsSync("/bsv")) {
      console.error(
        "%cerror%c: This command requires bsv environment. Prefix with `bsv env`.",
        "color: red",
        "",
      );
      Deno.exit(1);
    } else if (BSV_ROOT !== "/bsv" && !samefileSync("/bsv", BSV_ROOT)) {
      console.error(
        `%cerror%c: This script \`${import.meta.url}\` is not bound under /bsv.`,
        "color: red",
        "",
      );
      Deno.exit(1);
    }
  }

  await cmd.default(args._.slice(1));
}

if (import.meta.main) {
  await main();
}

export type Command = {
  default: (args: ReadonlyArray<string>) => void | Promise<void>;
  help: string;
  requiresBsvEnv: boolean;
};

export const commands: Record<string, Command> = {
  "act": await import("@bsv/cli/commands/act.ts"),
  "build": await import("@bsv/cli/commands/build.ts"),
  "build-shell": await import("@bsv/cli/commands/build_shell.ts"),
  "check": await import("@bsv/cli/commands/check.ts"),
  "delete": await import("@bsv/cli/commands/delete.ts"),
  "dev-shell": await import("@bsv/cli/commands/dev_shell.ts"),
  "env": await import("@bsv/cli/commands/env.ts"),
  "eval": await import("@bsv/cli/commands/eval.ts"),
  "fmt": await import("@bsv/cli/commands/fmt.ts"),
  "gc": await import("@bsv/cli/commands/gc.ts"),
  "gen-hash": await import("@bsv/cli/commands/gen_hash.ts"),
  "help": await import("@bsv/cli/commands/help.ts"),
  "init": await import("@bsv/cli/commands/init.ts"),
  "init-dev": await import("@bsv/cli/commands/init_dev.ts"),
  "list-commands": await import("@bsv/cli/commands/list_commands.ts"),
  "list-derivations": await import("@bsv/cli/commands/list_derivations.ts"),
  "log": await import("@bsv/cli/commands/log.ts"),
  "repl": await import("@bsv/cli/commands/repl.ts"),
  "run": await import("@bsv/cli/commands/run.ts"),
  "shell": await import("@bsv/cli/commands/shell.ts"),
  "verify-reproducibility": await import(
    "@bsv/cli/commands/verify_reproducibility.ts"
  ),
};

