import { assert } from "@std/assert";
import { basename } from "@std/path";
import * as Installable from "@bsv/cli/installable.ts";
import { printCommandHelp } from "@bsv/cli/print_command_help.ts";
import * as Nix from "@bsv/utils/nix/mod.ts";
import { parseArgs } from "@bsv/utils/parse_args.ts";
import { run, runCaptureOutput } from "@bsv/utils/run.ts";
import { samefileSync } from "@bsv/utils/samefile.ts";

export const help = "Enter the sandbox environment for building a derivation.";
export const requiresBsvEnv = true;

export default async (argv: ReadonlyArray<string>): Promise<void> => {
  const args = {
    bind: [],
    env: [],
    layer: [],
    "extra-tools": false,
    ...(parseArgs(argv, {
      boolean: ["extra-tools", "impure", "help"],
      collect: ["bind", "env"],
      negatable: ["extra-tools"],
      positional: true,
      string: ["command", "expr", "file"],
    })),
  };

  if (args.help) {
    printCommandHelp({
      name: "build-shell",
      synopsis: help,
      usage: "[options]... <derivation>",
      options: {
        "--bind=<host-path>:<sandbox-path>":
          "Bind additional path in the sandbox.",
        "--command=<command>": "Run command in the sandbox instead of a shell",
        "--env=<var>=<value>":
          "Set additional environemnt variable in the sandbox.",
        "--extra-tools|--no-extra-tools":
          "Include extra tools (gdb, strace, vim) in the sandbox.",
        "--help": "Print help message.",
        ...Installable.optionsHelp,
      },
    });
    return;
  }

  const drvArgs = Installable.parse(args);
  const drvResult = JSON.parse(
    await runCaptureOutput(["nix", "derivation", "show", ...drvArgs]),
  ) as Record<Nix.DerivationPath, Nix.Derivation>;
  const drvPath = Object.keys(drvResult)[0]!;

  const unresolvedDrv = drvResult[drvPath]!;

  if (
    !samefileSync(unresolvedDrv.builder, "/bsv/builders/bwrap-builder@v0") &&
    !samefileSync(unresolvedDrv.builder, "/bsv/builders/msys2-builder@v0") &&
    !samefileSync(unresolvedDrv.builder, "/bsv/builders/tart-builder@v0")
  ) {
    throw new Error(
      `Unsupported builder for build-shell: ${unresolvedDrv.builder}`,
    );
  }

  for (const inputDrv of Object.keys(unresolvedDrv.inputDrvs)) {
    await run([
      "nix",
      "build",
      "--no-link",
      "--print-build-logs",
      `${inputDrv}^*`,
    ]);
  }

  const drv = await Nix.resolvePlaceholders(unresolvedDrv);

  const tmpdir = Deno.makeTempDirSync({
    prefix: "bsv-build-shell-",
    suffix: `-${drv.name}`,
  });
  try {
    console.log(`Using temporary build directory: ${tmpdir}`);
    const nixAttrsJsonFile = `${tmpdir}/nix_attrs_json_file.json`;
    assert(drv.structuredAttrs);
    const attrs = structuredClone(drv.structuredAttrs);
    attrs["outputs"] = Object.fromEntries(
      Object.keys(drv.outputs).map((output) => {
        const name = `${drv.name}${output === "out" ? "" : `-${output}`}`;
        return [output, `/nix/store/oooooooooooooooooooooooooooooooo-${name}`];
      }),
    );
    Deno.writeTextFileSync(nixAttrsJsonFile, JSON.stringify(attrs));

    const extraBwrapArgs = [];

    const hostname = (() => {
      const name = basename(tmpdir);
      const prefixLen = name.length - `-${drv.name}`.length;
      const suffixLen = 63 - prefixLen;
      return name.substring(0, prefixLen) + "-" + name.slice(-suffixLen);
    })();
    extraBwrapArgs.push("--unshare-uts", "--hostname", hostname);

    if (args["extra-tools"]) {
      if (
        !samefileSync(unresolvedDrv.builder, "/bsv/builders/bwrap-builder@v0")
      ) {
        throw new Error(
          "--extra-tools is only supported on bwrap-builder@v0",
        );
      }

      let path = (attrs.env as Record<string, string>)?.PATH ??
        "/usr/local/bin:/usr/bin:/bin";
      for (const pkg of ["/bsv#gdb", "/bsv#strace", "/bsv#vim"]) {
        await run(["nix", "build", "--no-link", "--print-build-logs", pkg]);
        const { outPath } = (await Nix.realisationInfo(pkg))[0]!;
        const storePath = `/nix/store/${outPath}`;

        extraBwrapArgs.push("--ro-bind", storePath, storePath);
        path = `${storePath}/usr/local/bin:${path}`;

        if (pkg === "/bsv#vim") {
          extraBwrapArgs.push(
            "--setenv",
            "VIMRUNTIME",
            `${storePath}/usr/local/share/vim/vim91`,
          );
        }
      }

      extraBwrapArgs.push("--setenv", "PATH", path);
    }

    for (const bind of args.bind as Array<string>) {
      const [src, dst] = `${bind}`.split(":");
      extraBwrapArgs.push("--bind", src, dst);
    }
    for (const env of args.env as Array<string>) {
      const [key, value] = `${env}`.split("=");
      extraBwrapArgs.push("--setenv", key, value);
    }

    const nixBuildCores = await Nix.configShow("cores");

    for (const key of Object.keys(Deno.env.toObject())) {
      Deno.env.delete(key);
    }

    Deno.env.set("BSV_BUILD_SHELL", "1");
    Deno.env.set(
      "BSV_BUILD_SHELL_PS1",
      "\\[\\e[1;31m\\](\\H)\\[\\e[m\\] \\[\\e[1;34m\\]\\w\\[\\e[m\\]\\n \\[\\e[1;33m\\]\\$\\[\\e[m\\] ",
    );
    Deno.env.set("NIX_ATTRS_JSON_FILE", nixAttrsJsonFile);
    Deno.env.set("NIX_BUILD_CORES", nixBuildCores);
    Deno.env.set("NIX_BUILD_TOP", tmpdir);

    Deno.env.set(
      "BSV_BUILD_SHELL_EXTRA_BWRAP_ARGS",
      JSON.stringify(extraBwrapArgs),
    );

    if (args.command) {
      Deno.env.set("BSV_BUILD_SHELL_COMMAND", args.command);
    }
    try {
      await run([drv.builder]);
    } catch (_) { /* */ }
  } finally {
    Deno.removeSync(tmpdir, { recursive: true });
  }
};

