import { BSV_CACHE_URL } from "@bsv/cli/constants.ts";
import * as Nix from "@bsv/utils/nix/mod.ts";
import { runCaptureOutput } from "@bsv/utils/run.ts";

export const help = "Print build log of a derivation.";
export const requiresBsvEnv = true;

export default async (argv: ReadonlyArray<string>): Promise<void> => {
  // Forward argv to `nix derivation show` to resolve the installable to a
  // derivation path, which the cache fallback needs to locate the log.
  const result = JSON.parse(
    await runCaptureOutput(["nix", "derivation", "show", ...argv]),
  ) as Record<string, unknown>;
  const drvPaths = Object.keys(result);

  if (drvPaths.length === 0) {
    console.error("%cerror%c: no derivation given.", "color: red", "");
    Deno.exit(1);
  }

  if (drvPaths.length > 1) {
    console.error(
      "%cerror%c: expected a single derivation, but got multiple.",
      "color: red",
      "",
    );
    Deno.exit(1);
  }

  const drvPath = drvPaths[0]!;

  // Prefer the local build log under $NIX_LOG_DIR (only present when the
  // derivation was built here), then fall back to the build log stored on
  // the binary cache for derivations that were only substituted.
  const log = await Nix.log(drvPath, {}) ||
    await Nix.log(drvPath, { store: BSV_CACHE_URL });

  if (log.length === 0) {
    console.error(
      "%cerror%c: no build log found locally or on the binary cache.",
      "color: red",
      "",
    );
    Deno.exit(1);
  }

  await Deno.stdout.write(new TextEncoder().encode(log));
};

