import { assert } from "@std/assert";
import * as Installable from "@bsv/cli/installable.ts";
import { printCommandHelp } from "@bsv/cli/print_command_help.ts";
import { isExecutableSync } from "@bsv/utils/is_executable.ts";
import * as Nix from "@bsv/utils/nix/mod.ts";
import { parseArgs } from "@bsv/utils/parse_args.ts";
import { run, runCaptureOutput, spawn } from "@bsv/utils/run.ts";
import { samefileSync } from "@bsv/utils/samefile.ts";

export const help = "Rebuild a derivation and check if it is reproducible.";
export const requiresBsvEnv = true;

export default async (argv: ReadonlyArray<string>): Promise<void> => {
  // This is temporarily needed because `nix build --rebuild` does not work on
  // CA derivations, so we workaround by changing the env of the derivation.
  //
  // See: https://github.com/NixOS/nix/issues/11315

  const args = parseArgs(argv, {
    boolean: ["help", "impure"],
    positional: true,
    string: ["expr", "file"],
  });

  if (args.help) {
    printCommandHelp({
      name: "verify-reproducibility",
      synopsis: help,
      usage: "<derivation>",
      options: Installable.optionsHelp,
    });
    return;
  }

  const drvArgs = Installable.parse(args);
  const drvResult = JSON.parse(
    await runCaptureOutput(["nix", "derivation", "show", ...drvArgs]),
  ) as Record<Nix.DerivationPath, Nix.Derivation>;
  const drvPath1 = Object.keys(drvResult)[0]!;

  await run([
    "nix",
    "build",
    "--no-link",
    "--print-build-logs",
    `${drvPath1}^*`,
  ]);

  const drv1 = await Nix.derivationShow(drvPath1);
  if (
    !samefileSync(drv1.builder, "/bsv/builders/bwrap-builder@v0") &&
    !samefileSync(drv1.builder, "/bsv/builders/msys2-builder@v0")
  ) {
    throw new Error(
      `Unimplemented builder for verify-reproducibility: ${drv1.builder}`,
    );
  }
  assert(drv1.structuredAttrs);
  drv1.structuredAttrs["__bsv_verify_reproducibility_timestamp"] = Date.now();

  const child = spawn(["nix", "derivation", "add"], {
    stdin: "piped",
    stdout: "piped",
  });

  const writer = child.stdin.getWriter();
  try {
    await writer.write(new TextEncoder().encode(JSON.stringify(drv1)));
  } finally {
    await writer.close();
  }

  const status = await child.status;
  if (!status.success) {
    throw new Error(`command failed with exit code ${status.code}`);
  }
  const drvPath2 = (new TextDecoder().decode((await child.output()).stdout))
    .trimEnd();

  await run([
    "nix",
    "build",
    "--no-link",
    "--print-build-logs",
    `${drvPath2}^*`,
  ]);
  const realisations1 = await Nix.realisationInfo(drvPath1);
  const realisations2 = await Nix.realisationInfo(drvPath2);

  const outputs1 = new Map(
    realisations1.map((r) => [r.id.split("!")[1]!, r.outPath]),
  );
  const outputs2 = new Map(
    realisations2.map((r) => [r.id.split("!")[1]!, r.outPath]),
  );

  const mismatched: Array<
    { name: string; storePath1: string; storePath2: string }
  > = [];

  for (const name of Object.keys(drv1.outputs).sort()) {
    const outPath1 = outputs1.get(name);
    const outPath2 = outputs2.get(name);
    assert(
      outPath1,
      `Missing realisation for output "${name}" in original derivation`,
    );
    assert(
      outPath2,
      `Missing realisation for output "${name}" in re-built derivation`,
    );

    const storePath1 = `/nix/store/${outPath1}`;
    const storePath2 = `/nix/store/${outPath2}`;

    console.info(`Output ${name}:`);
    console.info(`  Original realisation: ${storePath1}`);
    console.info(`  Re-built realisation: ${storePath2}`);

    if (storePath1 !== storePath2) {
      mismatched.push({ name, storePath1, storePath2 });
    }
  }

  if (mismatched.length === 0) {
    console.info(`%cThe derivation is reproducible!`, "color: green");
  } else {
    console.error(
      `%cerror%c: The derivation is NOT reproducible!`,
      "color: red",
      "",
    );
    if (!isExecutableSync("diffoscope")) {
      console.error("Not running `diffoscope' as it is not installed.");
      return;
    }
    for (const { name, storePath1, storePath2 } of mismatched) {
      console.error(`Running diffoscope for output ${name}...`);
      await run([
        "diffoscope",
        "--exclude-directory-metadata=yes",
        storePath1,
        storePath2,
      ]);
    }
  }
};

