let
  bsv = {
    lib = import ./lib/default.nix;

    legacyPackages.aarch64-darwin = import ./pkgs/aarch64-darwin.nix;

    legacyPackages.aarch64-linux = import ./pkgs/aarch64-linux.nix;

    legacyPackages.x86_64-linux = import ./pkgs/x86_64-linux.nix;

    legacyPackages.x86_64-windows = import ./pkgs/x86_64-windows/default.nix;

    apps.x86_64-linux.qemu-system-n45 = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.qemu-system-n45}";
      meta.description = "QEMU system mode runner on Andes N45 for bare-metal ELF executables.";
    };

    apps.x86_64-linux.qemu-system-nx45 = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.qemu-system-nx45}";
      meta.description = "QEMU system mode runner on Andes NX45 for bare-metal ELF executables.";
    };

    apps.x86_64-linux.sid-n25f = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.sid-n25f}";
      meta.description = "SID runner on Andes N25F for bare-metal ELF executables.";
    };

    apps.x86_64-linux.sid-nx25f = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.sid-nx25f}";
      meta.description = "SID runner on Andes NX25F for bare-metal ELF executables.";
    };

    apps.x86_64-linux.sid-n45 = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.sid-n45}";
      meta.description = "SID runner on Andes N45 for bare-metal ELF executables.";
    };

    apps.x86_64-linux.sid-nx45 = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.sid-nx45}";
      meta.description = "SID runner on Andes NX45 for bare-metal ELF executables.";
    };

    formatter.x86_64-linux = bsv.legacyPackages.x86_64-linux.nixfmt-tree;

    apps.x86_64-linux.nix = {
