import { BSV_ROOT } from "@bsv/cli/constants.ts";
import { printCommandHelp } from "@bsv/cli/print_command_help.ts";
import { run } from "@bsv/utils/run.ts";

export const help = "Initialize development environment for BSV.";
export const requiresBsvEnv = true;

export default async (argv: ReadonlyArray<string>): Promise<void> => {
  if (argv.length > 0) {
    printCommandHelp({
      name: "init-dev",
      synopsis: help,
      usage: "",
    });
    return;
  }

  await run([
    "nix",
    "build",
    "--no-link",
    "--print-build-logs",
    `${BSV_ROOT}#nixd`,
    `${BSV_ROOT}#nixf-diagnose`,
    `${BSV_ROOT}#nixfmt-tree`,
    "--extra-substituters",
    "https://cache.nixos.org",
  ]);
};

import { assert } from "@std/assert";

/** The root of the bsv repository.  */
export const BSV_ROOT = Deno.realPathSync(`${import.meta.dirname}/../..`);

/**
 * The system of bsv in the format of `arch-os`.
 */
export const BSV_SYSTEM = `${Deno.build.arch}-${Deno.build.os}`;
assert(
  ["aarch64-darwin", "aarch64-linux", "x86_64-linux"].includes(BSV_SYSTEM),
);

/**
 * Path to the directory of pre-built Nix.
 */
export const BSV_NIX_PREFIX =
  "/nix/store/8in48708sfbv5n57xk43418ha7xfyp5x-nix-static-x86_64-unknown-linux-musl-2.31.2";

/**
 * Path to the pre-built bwrap executable.
 */
export const BSV_BWRAP_BIN = `${BSV_ROOT}/bin/bwrap`;

/**
 * Path to the local Nix store.
 */
export const BSV_NIX_DIR = `${BSV_ROOT}/nix`;

/**
 * Path to the temporary directory used by bsv.
 */
export const BSV_TMP_DIR = `${BSV_ROOT}/tmp`;

/**
 * URL of the binary cache used as a substituter and as the store that CI
 * uploads build outputs and build logs to.
 */
export const BSV_CACHE_URL = "https://atcbsv.andestech.com/cache";

