    "nds64le-elf-mculib-v5f"
    "nds64le-elf-mculib-v5d"
  ];

  linuxToolchains = [
    "nds32le-linux-glibc-v5d"
    "nds64le-linux-glibc-v5d"
    "nds32le-linux-musl-v5"
    "nds32le-linux-musl-v5d"
    "nds64le-linux-musl-v5"
    "nds64le-linux-musl-v5d"
  ];

  toolchainArchMap = import ../toolchain-arch-map.nix;

  archFlagsMap = import ../arch-flags-map.nix;

  flagsMap = import ../flags-map.nix;

  qemuRunnerMap = import ../qemu-runner-map.nix { inherit build; };

  test =
    lang: toolchain: arch: compiler: flags: runner:
    let
      xlen = build.andes.${toolchain}.target.config.xlen;
      CROSS_COMPILE = build.andes.${toolchain}.CROSS_COMPILE;
      target = build.andes.${toolchain}.target;
      os = target.triple.os;
      sysroot = "${build.andes.${toolchain}}/${build.andes.${toolchain}.sysroot}";
    in
    lib.bwrapDerivation {
      name = "${build.system}.${build.name}.tests.hello.${lang}.${toolchain}.${arch}.${compiler}.${flags}.${runner}";

      root = [
        build.stdenv-nocc
      ];

      env = {
        inherit (build) PATH;

        COMPILER =
          {
            "c" = "${CROSS_COMPILE}${compiler}";
            "c++" =
              {
                "gcc" = "${CROSS_COMPILE}g++";
                "clang" = "${CROSS_COMPILE}clang++";
              }
              .${compiler};
            "fortran" = "${CROSS_COMPILE}gfortran";
          }
          .${lang};

        FLAGS = "${archFlagsMap.${arch}} ${flagsMap.${os}.${flags}}";

        LDFLAGS =
          {
            elf = "-mvh";
            linux = "";
          }
          .${os};

        RUN =
          assert runner == "qemu";
          qemuRunnerMap.${os}.${xlen}.${arch};

        ${if os == "linux" then "QEMU_LD_PREFIX" else null} = sysroot;

        src =
          {
            "c" = ./hello.c;
            "c++" = ./hello.cpp;
            "fortran" = ./hello.f90;
          }
          .${lang};
      };

      builder = lib.bashBuilder ''
        mkdir --parents $out/
        $COMPILER $FLAGS --verbose $LDFLAGS $src -o $out/hello
        timeout --foreground --verbose 5 $RUN $out/hello | grep "^hello, world!$"
      '';

      system = build.system;
    };
in
lib.deepRecurseForDerivations
<| lib.mapDependentCartesianProduct test [
  [
    "c"
    "c++"
    "fortran"
  ]

  (lang: if lang != "fortran" then elfToolchains ++ linuxToolchains else linuxToolchains)

  (_: toolchain: toolchainArchMap.${toolchain})

  (
    lang: _: _:
    if lang != "fortran" then
      [
        "gcc"
        "clang"
      ]
    else
      [ "gcc" ]
  )

  (
    _: toolchain: _: _:
    builtins.attrNames flagsMap.${build.andes.${toolchain}.target.triple.os}
  )

  (_: _: _: _: _: [ "qemu" ])
]

