import { emptyDirSync } from "@std/fs";
import { printCommandHelp } from "@bsv/cli/print_command_help.ts";
import * as Nix from "@bsv/utils/nix/mod.ts";
import { parseArgs } from "@bsv/utils/parse_args.ts";
import { run, runCaptureOutput } from "@bsv/utils/run.ts";

export const help = "Delete Nix store objects and their referrers closure.";
export const requiresBsvEnv = true;

export default async (argv: ReadonlyArray<string>): Promise<void> => {
  const args = parseArgs(argv, {
    boolean: ["all", "dry-run", "help", "yes"],
    positional: true,
  });

  if (args.help) {
    printCommandHelp({
      name: "delete",
      synopsis: help,
      usage: "[options]... <installable>...",
      options: {
        "--all": "Delete all Nix store objects.",
        "--dry-run": "Do not perform actual deletion.",
        "--help": "Print help message.",
        "--yes": "Proceed without asking for confirmation.",
      },
    });
    return;
  }

  if (args["all"]) {
    const bsvGcRoot = "/nix/var/nix/gcroots/bsv";

    if (!args["yes"]) {
      const proceed = confirm(
        `Remove ALL Nix store objects. Proceed?`,
      );
      if (!proceed) {
        return;
      }
    }

    if (!args["dry-run"]) {
      emptyDirSync(bsvGcRoot);
      await run(["nix", "store", "gc", "--verbose"]);
    }
    return;
  }

  const paths = JSON.parse(
    await runCaptureOutput(["nix", "path-info", "--json", ...args._]),
  ) as Record<string, Nix.PathInfo>;

  const referrersClosure = ((await runCaptureOutput([
    "nix-store",
    "--query",
    "--referrers-closure",
    ...Object.keys(paths),
  ])) as string).trim().split("\n");

  if (!args["yes"]) {
    const proceed = confirm([
      "Remove the following Nix store paths:",
      ...referrersClosure.map((s) => `  ${s}`),
      "Proceed?",
    ].join("\n"));

    if (!proceed) {
      return;
    }
  }

  if (args["dry-run"]) {
    return;
  }

  await run([
    "nix",
    "store",
    "delete",
    "--ignore-liveness",
    ...referrersClosure,
  ]);
};

