import { printCommandHelp } from "@bsv/cli/print_command_help.ts";
import { stdoutConsole } from "@bsv/utils/console.ts";

export const help = "List available commands.";
export const requiresBsvEnv = false;

export default async (argv: ReadonlyArray<string>): Promise<void> => {
  if (argv.length > 0) {
    printCommandHelp({
      name: "list-commands",
      synopsis: help,
      usage: "",
    });
    return;
  }

  const { commands } = await import("@bsv/cli/commands.ts");
  for (const command of Object.keys(commands)) {
    stdoutConsole.log(command);
  }
};

